#f5f4ff}.column .type{color:#6d64ef;font-size:12px;font-weight:800}.system{color:#98a2b5;font-size:13px}.remove{padding:2px 7px;background:transparent;color:#a5adbc;font-size:18px}.add{margin:15px auto 0;display:block}.inspector{padding:18px;border:1px solid var(--line);border-radius:12px;background:#fff}.inspector h3{margin:0}.inspector p{margin:4px 0 15px;color:var(--muted);font-size:13px}.checks{display:flex;gap:10px;margin-top:14px}.checks label{display:flex;align-items:center;gap:6px}.checks input{width:auto;margin:0;accent-color:var(--brand)}.empty{color:var(--muted);font-size:13px}.choice{display:flex;align-items:center;gap:8px;padding:10px 12px;border:1px solid #dce1eb;border-radius:9px;cursor:pointer}.choice input{width:auto;margin:0;accent-color:var(--brand)}.choice-row{display:flex;flex-wrap:wrap;gap:9px}.access{display:grid;grid-template-columns:1fr 1fr;gap:20px}.box{padding:18px;border:1px solid var(--line);border-radius:12px}.box h3{margin:0 0 5px}.box p{margin:0 0 13px;color:var(--muted);font-size:13px}.error{margin:8px 0 0;color:#c0364e;font-size:13px;font-weight:700}@media(max-width:820px){.templates{grid-template-columns:1fr 1fr}.schema-layout,.access{grid-template-columns:1fr}.canvas{padding:18px}.inspector{max-width:660px;margin:auto}.grid{grid-template-columns:1fr}.span2{grid-column:auto}}@media(max-width:520px){.shell{padding:25px 14px 45px}.hero{display:block}.badge{display:inline-block;margin-top:12px}.steps{grid-template-columns:1fr}.templates{grid-template-columns:1fr}.card{padding:20px}.model-bar{display:block}.table-name{margin-top:10px}.actions{flex-direction:column-reverse}.actions button{width:100%}}
