:stroke;cursor:pointer}#links .many .line{stroke-dasharray:7 5}#links .on .line{stroke:#e0527a;stroke-width:3}#links text{fill:#504ac2;font-size:13px;font-weight:800}#links .temp{fill:none;stroke:#16a37f;stroke-width:2.5;stroke-dasharray:5 4}.rel{margin-bottom:10px;padding:12px;border:1px solid var(--line);border-radius:10px;cursor:pointer}.rel.on{border-color:#e0527a;background:#fff8fa}.rel-title{display:flex;gap:7px;align-items:center;margin-bottom:8px;font-size:13px}.rel-title span{color:var(--muted)}.rel select{margin-top:0}.mini{display:flex;gap:6px;align-items:center;margin-top:9px;font-weight:600}.mini input{width:auto;margin:0}.rel-note{margin-top:8px;color:var(--muted);font-size:12px}.rel-actions{display:flex;gap:8px;margin-top:10px}.rel-actions button,.danger-link{padding:5px 10px;font-size:12px}.danger,.danger-link{color:#c0364e}.danger-link{margin-top:10px;background:#fdecef}.danger-link:disabled{opacity:.4;cursor:not-allowed}.inspector hr{margin:18px 0;border:0;border-top:1px solid var(--line)}.inspector{position:sticky;top:16px;max-height:640px;overflow:auto}@media(max-width:820px){.canvas{height:520px}.inspector{position:static;max-height:none}}
