<script>
const TYPES=['string','text','integer','bigInteger','boolean','date','dateTime','decimal'];
const REL={hasMany:'One to many',hasOne:'One to one',belongsToMany:'Many to many'};
const NAME_RE=/^[A-Za-z][A-Za-z0-9_]*$/;
const templates={
 store:{description:'online store with products, categories and orders',roles:'admin, manager, customer',tables:[{name:'Category',fields:[['name','string'],['description','text']]},{name:'Product',fields:[['name','string'],['sku','string'],['price','decimal'],['stock','integer'],['description','text']]},{name:'Order',fields:[['number','string'],['total','decimal'],['status','string']]}],relations:[['Category','Product','hasMany'],['Order','Product','belongsToMany']]},
 saas:{description:'teams organize projects and track tasks',roles:'admin, manager, member',tables:[{name:'Team',fields:[['name','string']]},{name:'Project',fields:[['name','string'],['description','text'],['status','string'],['starts_at','date'],['due_at','date']]},{name:'Task',fields:[['title','string'],['status','string'],['due_at','date']]}],relations:[['Team','Project','hasMany'],['Project','Task','hasMany']]},
 clinic:{description:'patients, doctors and appointments',roles:'admin, receptionist, doctor',tables:[{name:'Patient',fields:[['name','string'],['phone','string'],['email','string'],['birth_date','date'],['notes','text']]},{name:'Doctor',fields:[['name','string'],['specialty','string']]},{name:'Appointment',fields:[['starts_at','dateTime'],['notes','text']]}],relations:[['Patient','Appointment','hasMany'],['Doctor','Appointment','hasMany']]},
 restaurant:{description:'menu items, reservations and customer orders',roles:'admin, manager, staff',tables:[{name:'MenuCategory',fields:[['name','string']]},{name:'MenuItem',fields:[['name','string'],['price','decimal'],['description','text'],['available','boolean']]},{name:'Reservation',fields:[['guest_name','string'],['party_size','integer'],['reserved_at','dateTime']]}],relations:[['MenuCategory','MenuItem','hasMany']]}
};
let step=1,uid=1,tables=[],relations=[],activeId=null,selCol=0,selRel=null,tab='inspector',colDrag=null,moving=null,linking=null;
const $=s=>document.querySelector(s);
const form=$('#studio-form'),panels=document.querySelectorAll('.panel'),steps=document.querySelectorAll('.step'),cardsEl=$('#cards'),svg=$('#links'),stage=$('#stage'),canvas=$('#canvas'),inspector=$('#inspector'),errorBox=$('#schema-error');
const esc=v=>String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
const snake=v=>v.trim().replace(/([a-z0-9])([A-Z])/g,'$1_$2').replace(/\s+/g,'_').toLowerCase();
const plural=w=>!w?'':w.endsWith('s')?w:/[^aeiou]y$/.test(w)?w.slice(0,-1)+'ies':/(x|z|ch|sh)$/.test(w)?w+'es':w+'s';
const singular=w=>/[^aeiou]ies$/.test(w)?w.slice(0,-3)+'y':/(ses|xes|zes|ches|shes)$/.test(w)?w.slice(0,-2):/[^s]s$/.test(w)?w.slice(0,-1):w;
const tableOf=t=>plural(snake(t.name))||'table';
const byId=id=>tables.find(t=>t.id===id);
const active=()=>byId(activeId);
const cardEl=id=>cardsEl.querySelector(`[data-table="${id}"]`);
const blank=()=>({name:'',type:'string',nullable:false,unique:false,default:''});
const fkName=r=>singular(tableOf(byId(r.from)))+'_id';
const pivotName=r=>[singular(tableOf(byId(r.from))),singular(tableOf(byId(r.to)))].sort().join('_');
const fksOf=t=>relations.filter(r=>r.type!=='belongsToMany'&&r.to===t.id);

function addTable(name,fields,x,y){const t={id:uid++,name,x:x==null?40+(tables.length%3)*440:x,y:y==null?40+Math.floor(tables.length/3)*360:y,fields:fields.map(([n,type])=>({...blank(),name:n,type}))};tables.push(t);return t}

/* ---------- canvas rendering ---------- */
function colHtml(t,f,i){return `<div class="column ${t.id===activeId&&i===selCol?'selected':''}" data-column="${i}"><span class="grip" draggable="true" title="Drag to reorder">⋮⋮</span><input class="cn" data-name value="${esc(f.name)}" placeholder="column_name" spellcheck="false"><select class="ct" data-type>${TYPES.map(x=>`<option ${x===f.type?'selected':''}>${x}</option>`).join('')}</select><span class="flags">${f.nullable?'<span class="flag">N</span>':''}${f.unique?'<span class="flag u">U</span>':''}${f.default!==''?'<span class="flag d">D</span>':''}</span><span class="row-actions"><button type="button" data-act="dup" title="Duplicate">⧉</button><button type="button" class="del" data-act="del" title="Delete">×</button></span></div>`}
function cardHtml(t){return `<div class="table-card ${t.id===activeId?'active':''}" data-table="${t.id}" style="left:${t.x}px;top:${t.y}px"><div class="table-head"><span class="title"><strong>${esc(t.name||'Untitled')}</strong><small>${esc(tableOf(t))}</small></span><span class="link-handle" title="Drag onto another table to create a relation">●</span></div><div class="system"><span>🔑</span><b>id</b><span>bigIncrements</span></div>${fksOf(t).map(r=>`<div class="system fk"><span>🔗</span><b>${esc(fkName(r))}</b><span>foreignId${r.nullable?' · null':''}</span></div>`).join('')}<div class="cols">${t.fields.map((f,i)=>colHtml(t,f,i)).join('')}</div><div class="system"><span>◷</span><b>created_at</b><span>timestamp</span></div><div class="system"><span>◷</span><b>updated_at</b><span>timestamp</span></div><button type="button" class="add-row" data-add>＋ Add column</button></div>`}
function renderCards(){cardsEl.innerHTML=tables.map(cardHtml).join('');sizeStage();drawLinks()}
function sizeStage(){let w=0,h=0;cardsEl.querySelectorAll('.table-card').forEach(c=>{w=Math.max(w,c.offsetLeft+c.offsetWidth);h=Math.max(h,c.offsetTop+c.offsetHeight)});stage.style.width=Math.max(canvas.clientWidth,w+80)+'px';stage.style.height=Math.max(canvas.clientHeight,h+80)+'px'}
function anchors(a,b){const ay=a.offsetTop+24,by=b.offsetTop+24,al=a.offsetLeft,ar=al+a.offsetWidth,bl=b.offsetLeft,br=bl+b.offsetWidth;if(ar+30<=bl)return{x1:ar,y1:ay,x2:bl,y2:by,d1:1,d2:-1};if(br+30<=al)return{x1:al,y1:ay,x2:br,y2:by,d1:-1,d2:1};return{x1:ar,y1:ay,x2:br,y2:by,d1:1,d2:1}}
function drawLinks(){svg.innerHTML=relations.map((r,i)=>{const a=cardEl(r.from),b=cardEl(r.to);if(!a||!b)return'';const p=anchors(a,b),k=Math.max(50,Math.abs(p.x2-p.x1)/2),d=`M${p.x1} ${p.y1} C${p.x1+p.d1*k} ${p.y1} ${p.x2+p.d2*k} ${p.y2} ${p.x2} ${p.y2}`,many=r.type==='belongsToMany',end=r.type==='hasOne'?'1':'∞',label=(x,y,dir,t)=>`<text x="${x+dir*8}" y="${y-8}" text-anchor="${dir>0?'start':'end'}">${t}</text>`;return `<g class="rel-line ${i===selRel?'on':''} ${many?'many':''}"><path class="hit" data-rel="${i}" d="${d}"/><path class="line" d="${d}"/>${label(p.x1,p.y1,p.d1,many?'∞':'1')}${label(p.x2,p.y2,p.d2,end)}</g>`}).join('')}
function activate(id,col){activeId=id;if(col!=null)selCol=col;else if(selCol>=active().fields.length)selCol=0;cardsEl.querySelectorAll('.table-card').forEach(c=>{c.classList.toggle('active',+c.dataset.table===id);c.querySelectorAll('.column').forEach((row,i)=>row.classList.toggle('selected',+c.dataset.table===id&&i===selCol))});drawInspector()}

/* ---------- inspector ---------- */
function migrationFor(t){const q=v=>/^-?\d+(\.\d+)?$/.test(v)?v:"'"+String(v).replace(/\\/g,'\\\\').replace(/'/g,"\\'")+"'";const lines=fksOf(t).map(r=>`    $table->foreignId(<em>'${esc(fkName(r))}'</em>)${r.nullable?'->nullable()':''}->constrained(<em>'${esc(tableOf(byId(r.from)))}'</em>)${r.nullable?'->nullOnDelete()':'->cascadeOnDelete()'}${r.type==='hasOne'?'->unique()':''};`).concat(t.fields.map(f=>{let l=`    $table->${f.type}(<em>'${esc(f.name||'untitled')}'</em>${f.type==='decimal'?', 8, 2':''})`;if(f.nullable)l+='->nullable()';if(f.unique)l+='->unique()';if(f.default!=='')l+=`->default(<i>${esc(f.type==='boolean'?(/^(1|true)$/i.test(f.default)?'true':'false'):q(f.default))}</i>)`;return l+';'}));let out=`Schema::create(<em>'${esc(tableOf(t))}'</em>, function (Blueprint $table) {\n    $table->id();\n${lines.join('\n')}${lines.length?'\n':''}    $table->timestamps();\n});`;relations.filter(r=>r.type==='belongsToMany'&&(r.from===t.id||r.to===t.id)).forEach(r=>{const a=singular(tableOf(byId(r.from)))+'_id',b=singular(tableOf(byId(r.to)))+'_id';out+=`\n\n// pivot\nSchema::create(<em>'${esc(pivotName(r))}'</em>, function (Blueprint $table) {\n    $table->foreignId(<em>'${esc(a)}'</em>)->constrained(<em>'${esc(tableOf(byId(r.from)))}'</em>)->cascadeOnDelete();\n    $table->foreignId(<em>'${esc(b)}'</em>)->constrained(<em>'${esc(tableOf(byId(r.to)))}'</em>)->cascadeOnDelete();\n    $table->primary([<em>'${esc(a)}'</em>, <em>'${esc(b)}'</em>]);\n});`});return out}
function relNote(r){return r.type==='belongsToMany'?`Creates pivot table <b>${esc(pivotName(r))}</b>.`:`Adds <b>${esc(fkName(r))}</b> to <b>${esc(tableOf(byId(r.to)))}</b>${r.type==='hasOne'?' (unique)':''}.`}
function drawInspector(){const t=active(),tabs=`<div class="tabs">${[['inspector','Inspector'],['relations','Relations ('+relations.length+')'],['migration','Migration']].map(([k,l])=>`<button type="button" data-tab="${k}" class="${tab===k?'on':''}">${l}</button>`).join('')}</div>`;
 if(!t){inspector.innerHTML=tabs+'<p>Add a table to begin.</p>';return}
 if(tab==='migration'){inspector.innerHTML=`${tabs}<h3>Migration · ${esc(tableOf(t))}</h3><p>Generated live, including foreign keys and pivots.</p><pre class="code">${migrationFor(t)}</pre><button type="button" class="copy" data-copy>Copy code</button>`;return}
 if(tab==='relations'){inspector.innerHTML=tabs+'<h3>Relations</h3><p>Drag the ● handle of one table onto another to connect them.</p>'+(relations.length?relations.map((r,i)=>`<div class="rel ${i===selRel?'on':''}" data-rel-card="${i}"><div class="rel-title"><b>${esc(byId(r.from).name)}</b><span>→</span><b>${esc(byId(r.to).name)}</b></div><select data-rel-type="${i}">${Object.entries(REL).map(([k,l])=>`<option value="${k}" ${k===r.type?'selected':''}>${l}</option>`).join('')}</select>${r.type!=='belongsToMany'?`<label class="mini"><input type="checkbox" data-rel-null="${i}" ${r.nullable?'checked':''}>Optional (nullable foreign key)</label>`:''}<div class="rel-note">${relNote(r)}</div><div class="rel-actions"><button type="button" data-rel-swap="${i}">⇄ Swap</button><button type="button" class="danger" data-rel-del="${i}">Remove</button></div></div>`).join(''):'<div class="empty">No relations yet.</div>');return}
 const f=t.fields[selCol];
 inspector.innerHTML=`${tabs}<h3>Table</h3><label>Table name<input data-tname value="${esc(t.name)}" placeholder="Product"></label><div class="rel-note">Table: <b>${esc(tableOf(t))}</b></div><button type="button" class="danger-link" data-del-table ${tables.length<2?'disabled':''}>Delete table</button><hr><h3>Column inspector</h3>`+(f?`<p>Changes are reflected on the canvas immediately.</p><label>Column name<input data-f="name" value="${esc(f.name)}"></label><label>Database type<select data-f="type">${TYPES.map(x=>`<option ${x===f.type?'selected':''}>${x}</option>`).join('')}</select></label><div class="checks"><label><input data-f="nullable" type="checkbox" ${f.nullable?'checked':''}>Nullable</label><label><input data-f="unique" type="checkbox" ${f.unique?'checked':''}>Unique</label></div><label>Default value<input data-f="default" value="${esc(f.default)}" placeholder="Optional"></label>`:'<p>Select a column on the canvas.</p>')}

inspector.onclick=e=>{const b=e.target.closest('button,[data-rel-card]');if(!b)return;const t=active();
 if(b.dataset.tab){tab=b.dataset.tab;drawInspector();return}
 if(b.dataset.copy){navigator.clipboard&&navigator.clipboard.writeText($('.code').textContent);b.textContent='Copied ✓';return}
 if('delTable' in b.dataset){if(tables.length<2)return;tables=tables.filter(x=>x.id!==t.id);relations=relations.filter(r=>r.from!==t.id&&r.to!==t.id);selRel=null;activeId=tables[0].id;selCol=0;renderCards();drawInspector();return}
 if('relDel' in b.dataset){relations.splice(+b.dataset.relDel,1);selRel=null;renderCards();drawInspector();return}
 if('relSwap' in b.dataset){const r=relations[+b.dataset.relSwap];[r.from,r.to]=[r.to,r.from];renderCards();drawInspector();return}
 if('relCard' in b.dataset&&b.tagName!=='BUTTON'){selRel=+b.dataset.relCard;drawLinks();inspector.querySelectorAll('.rel').forEach((el,i)=>el.classList.toggle('on',i===selRel))}};
inspector.oninput=e=>{const t=active(),el=e.target;
 if('tname' in el.dataset){t.name=el.value;renderCards();return}
 if(el.dataset.f){const f=t.fields[selCol];f[el.dataset.f]=el.type==='checkbox'?el.checked:el.value;renderCards();return}
 if('relType' in el.dataset){const r=relations[+el.dataset.relType];r.type=el.value;renderCards();drawInspector();return}
 if('relNull' in el.dataset){relations[+el.dataset.relNull].nullable=el.checked;renderCards()}};

/* ---------- canvas interaction ---------- */
function addColumn(t){t.fields.push({...blank(),name:'field_'+(t.fields.length+1)});activeId=t.id;selCol=t.fields.length-1;tab='inspector';renderCards();drawInspector();const input=cardEl(t.id).querySelector(`[data-column="${selCol}"] [data-name]`);input.focus();input.select()}
cardsEl.addEventListener('click',e=>{const card=e.target.closest('.table-card');if(!card)return;const t=byId(+card.dataset.table);
 if(e.target.closest('[data-add]')){addColumn(t);return}
 const row=e.target.closest('[data-column]');
 if(row){const i=+row.dataset.column,act=e.target.closest('[data-act]')&&e.target.closest('[data-act]').dataset.act;
  if(act==='del'){t.fields.splice(i,1);activeId=t.id;selCol=Math.max(0,Math.min(selCol,t.fields.length-1));renderCards();drawInspector();return}
  if(act==='dup'){t.fields.splice(i+1,0,{...t.fields[i],name:t.fields[i].name+'_copy'});activeId=t.id;selCol=i+1;renderCards();drawInspector();return}
  tab='inspector';activate(t.id,i);return}
 tab='inspector';activate(t.id)});
cardsEl.addEventListener('input',e=>{if(!e.target.matches('[data-name]'))return;const card=e.target.closest('.table-card'),t=byId(+card.dataset.table),i=+e.target.closest('[data-column]').dataset.column;t.fields[i].name=e.target.value;if(t.id===activeId&&i===selCol){const box=inspector.querySelector('[data-f="name"]');if(box)box.value=e.target.value}if(tab==='migration')drawInspector()});
cardsEl.addEventListener('change',e=>{if(!e.target.matches('[data-type]'))return;const card=e.target.closest('.table-card'),t=byId(+card.dataset.table);t.fields[+e.target.closest('[data-column]').dataset.column].type=e.target.value;activeId=t.id;selCol=+e.target.closest('[data-column]').dataset.column;renderCards();drawInspector()});
cardsEl.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-name]')){e.preventDefault();addColumn(byId(+e.target.closest('.table-card').dataset.table))}});
cardsEl.addEventListener('dragstart',e=>{const grip=e.target.closest&&e.target.closest('.grip');if(!grip)return;const row=grip.closest('[data-column]');colDrag={t:+grip.closest('.table-card').dataset.table,i:+row.dataset.column};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain','column');e.dataTransfer.setDragImage(row,12,12)});
cardsEl.addEventListener('dragover',e=>{if(!colDrag)return;const row=e.target.closest('[data-column]');if(!row||+row.closest('.table-card').dataset.table!==colDrag.t)return;e.preventDefault();cardsEl.querySelectorAll('.over').forEach(x=>x.classList.remove('over'));row.classList.add('over')});
cardsEl.addEventListener('drop',e=>{if(!colDrag)return;e.preventDefault();const row=e.target.closest('[data-column]');if(row&&+row.closest('.table-card').dataset.table===colDrag.t){const t=byId(colDrag.t),to=+row.dataset.column,[m]=t.fields.splice(colDrag.i,1);t.fields.splice(to,0,m);activeId=t.id;selCol=to}colDrag=null;renderCards();drawInspector()});
cardsEl.addEventListener('dragend',()=>{colDrag=null;cardsEl.querySelectorAll('.over').forEach(x=>x.classList.remove('over'))});
cardsEl.addEventListener('pointerdown',e=>{const card=e.target.closest('.table-card');if(!card||e.button)return;const t=byId(+card.dataset.table),sr=stage.getBoundingClientRect();
 if(e.target.closest('.link-handle')){e.preventDefault();linking={from:t.id};svg.insertAdjacentHTML('beforeend','<path id="temp-link" class="temp"/>');const a=card.offsetLeft+card.offsetWidth,y=card.offsetTop+24;linking.x=a;linking.y=y;return}
 if(e.target.closest('.table-head')){e.preventDefault();tab=tab==='migration'?tab:'inspector';activate(t.id);moving={t,card,sx:e.clientX,sy:e.clientY,ox:t.x,oy:t.y}}});
window.addEventListener('pointermove',e=>{if(moving){moving.t.x=Math.max(0,moving.ox+e.clientX-moving.sx);moving.t.y=Math.max(0,moving.oy+e.clientY-moving.sy);moving.card.style.left=moving.t.x+'px';moving.card.style.top=moving.t.y+'px';drawLinks()}
 if(linking){const sr=stage.getBoundingClientRect(),x=e.clientX-sr.left,y=e.clientY-sr.top,k=Math.max(40,Math.abs(x-linking.x)/2);$('#temp-link').setAttribute('d',`M${linking.x} ${linking.y} C${linking.x+k} ${linking.y} ${x-k} ${y} ${x} ${y}`);const over=document.elementFromPoint(e.clientX,e.clientY),target=over&&over.closest('.table-card');cardsEl.querySelectorAll('.drop-target').forEach(c=>c.classList.remove('drop-target'));if(target&&+target.dataset.table!==linking.from)target.classList.add('drop-target')}});
window.addEventListener('pointerup',e=>{if(moving){moving=null;sizeStage()}
 if(linking){const tmp=$('#temp-link');if(tmp)tmp.remove();cardsEl.querySelectorAll('.drop-target').forEach(c=>c.classList.remove('drop-target'));const over=document.elementFromPoint(e.clientX,e.clientY),target=over&&over.closest('.table-card'),from=linking.from;linking=null;if(target&&+target.dataset.table!==from){const to=+target.dataset.table;if(!relations.some(r=>r.from===from&&r.to===to)){relations.push({from,to,type:'hasMany',nullable:false});selRel=relations.length-1;tab='relations';renderCards();drawInspector()}}}});
svg.addEventListener('click',e=>{const p=e.target.closest('[data-rel]');if(p){selRel=+p.dataset.rel;tab='relations';drawLinks();drawInspector()}});
$('#add-table').onclick=()=>{const t=addTable('Table'+(tables.length+1),[['name','string']]);activeId=t.id;selCol=0;tab='inspector';renderCards();drawInspector();const c=cardEl(t.id);c.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'})};
function autoLayout(){const level={};tables.forEach(t=>level[t.id]=0);for(let k=0;k<tables.length;k++)relations.forEach(r=>{if(r.type!=='belongsToMany'&&level[r.from]<tables.length)level[r.to]=Math.max(level[r.to],level[r.from]+1)});const ys={};tables.forEach(t=>{const l=level[t.id];if(ys[l]==null)ys[l]=40;const el=cardEl(t.id);t.x=40+l*420;t.y=ys[l];ys[l]+=((el&&el.offsetHeight)||150+t.fields.length*40)+36});renderCards()}
$('#auto-layout').onclick=autoLayout;

/* ---------- validation & wizard ---------- */
function schemaError(){if(!tables.length)return{msg:'Add at least one table.'};const seen=new Set();for(const t of tables){if(!NAME_RE.test(t.name))return{t,msg:`Table name "${t.name||''}" must start with a letter and use letters, numbers or underscores.`};if(seen.has(t.name.toLowerCase()))return{t,msg:`Duplicate table name "${t.name}".`};seen.add(t.name.toLowerCase());if(!t.fields.length)return{t,msg:`${t.name} needs at least one column.`};const cols=new Set(fksOf(t).map(fkName));for(const [i,f] of t.fields.entries()){if(!NAME_RE.test(f.name))return{t,i,msg:`Column "${f.name||''}" in ${t.name} must start with a letter and use letters, numbers or underscores.`};const n=snake(f.name);if(cols.has(n))return{t,i,msg:`Duplicate column "${n}" in ${t.name}.`};cols.add(n)}}
 const state={};const walk=id=>{if(state[id]===2)return false;if(state[id]===1)return true;state[id]=1;const cyc=relations.some(r=>r.type!=='belongsToMany'&&r.from===id&&walk(r.to));state[id]=2;return cyc};if(tables.some(t=>walk(t.id)))return{msg:'Relations form a cycle, so the migrations cannot be ordered.'};return null}
function validSchema(){const err=schemaError();errorBox.hidden=!err;if(!err)return true;errorBox.textContent=err.msg;if(err.t){tab='inspector';activeId=err.t.id;selCol=err.i==null?selCol:err.i;renderCards();drawInspector()}return false}
function validateCurrent(){if(step===1){const input=form.querySelector('[name="project[name]"]');if(!input.value.trim()){input.focus();input.setCustomValidity('Please complete this field.');input.reportValidity();input.setCustomValidity('');return false}}if(step===2)return validSchema();return true}
function show(next){step=next;panels.forEach(p=>p.classList.toggle('active',+p.dataset.panel===step));steps.forEach(s=>s.classList.toggle('active',+s.dataset.step<=step));if(step===2){sizeStage();drawLinks()}window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('.next').forEach(button=>button.onclick=()=>{if(!validateCurrent())return;if(step===1){$('#resource-roles').value=form.querySelector('[name="project[roles]"]').value;const locale=form.querySelector('[name="project[locale]"]').value;form.querySelectorAll('[name="locales[]"]').forEach(box=>box.checked=box.value===locale)}show(step+1)});
document.querySelectorAll('.back').forEach(button=>button.onclick=()=>show(step-1));
$('#templates').onclick=e=>{const card=e.target.closest('[data-template]');if(!card)return;const tpl=templates[card.dataset.template];document.querySelectorAll('.template').forEach(item=>item.classList.toggle('selected',item===card));form.querySelector('[name="project[description]"]').value=tpl.description;form.querySelector('[name="project[roles]"]').value=tpl.roles;const name=form.querySelector('[name="project[name]"]');if(!name.value.trim())name.value=tpl.tables[0].name+' Workspace';tables=[];relations=[];tpl.tables.forEach(t=>addTable(t.name,t.fields));tpl.relations.forEach(([a,b,type])=>relations.push({from:tables.find(t=>t.name===a).id,to:tables.find(t=>t.name===b).id,type,nullable:false}));activeId=tables[0].id;selCol=0;selRel=null;tab='inspector';renderCards();autoLayout();drawInspector()};
form.addEventListener('submit',e=>{if(!validateCurrent()){e.preventDefault();return}if(!form.querySelector('[name="project[name]"]').value.trim()){e.preventDefault();show(1);validateCurrent();return}if(!validSchema()){e.preventDefault();show(2);return}
 form.querySelectorAll('[data-generated]').forEach(n=>n.remove());const add=(name,value)=>{const input=document.createElement('input');input.type='hidden';input.name=name;input.value=value;input.dataset.generated='1';form.append(input)};
 tables.forEach((t,ti)=>{add(`tables[${ti}][name]`,t.name);t.fields.forEach((field,index)=>{for(const [key,value] of Object.entries(field)){if(value===false||value==='')continue;add(`tables[${ti}][fields][${index}][${key}]`,value===true?'1':value)}})});
 relations.forEach((r,ri)=>{add(`relations[${ri}][from]`,byId(r.from).name);add(`relations[${ri}][to]`,byId(r.to).name);add(`relations[${ri}][type]`,r.type);if(r.nullable)add(`relations[${ri}][nullable]`,'1')})});
window.addEventListener('resize',sizeStage);
const first=addTable('Product',[['name','string']],40,40);activeId=first.id;renderCards();drawInspector();
</script>
</body></html>
